package dev.soundceiling.app;
import android.app.Activity;import android.content.*;import android.net.Uri;import android.os.Environment;import android.provider.Settings;
final class LogAccess{static boolean openFolder(Activity a){try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);a.startActivity(i);return true;}catch(RuntimeException e){return false;}}static boolean shareLatest(Activity a){String raw=Prefs.get(a).getString(Prefs.LAST_LOG_URI,"");if(raw.isEmpty())return false;try{Uri u=Uri.parse(raw);Intent i=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_STREAM,u).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);a.startActivity(Intent.createChooser(i,"Поделиться логом"));return true;}catch(RuntimeException e){return false;}}private LogAccess(){}}
